def configure_optimizers(self, weight_decay, learning_rate, betas, device_type):
    param_dict = {pn: p for pn, p in self.named_parameters() if p.requires_grad}
    decay_params = [p for n, p in param_dict.items() if p.dim() >= 2]
    nodecay_params = [p for n, p in param_dict.items() if p.dim() < 2]
    optim_groups = [
        {'params': decay_params, 'weight_decay': weight_decay},
        {'params': nodecay_params, 'weight_decay': 0.0},
    ]
    num_decay_params = sum(p.numel() for p in decay_params)
    num_nodecay_params = sum(p.numel() for p in nodecay_params)
    print(f"num decayed parameter tensors: {len(decay_params)}, with {num_decay_params:,} parameters")
    print(f"num non-decayed parameter tensors: {len(nodecay_params)}, with {num_nodecay_params:,} parameters")

    class RAdam(torch.optim.Optimizer):
        """Rectified Adam optimizer (Liu et al., 2019) with decoupled weight decay."""
        def __init__(self, params, lr=1e-3, betas=(0.9, 0.999), eps=1e-8, weight_decay=0):
            defaults = dict(lr=lr, betas=betas, eps=eps, weight_decay=weight_decay)
            super().__init__(params, defaults)

        @torch.no_grad()
        def step(self):
            for group in self.param_groups:
                for p in group['params']:
                    if p.grad is None:
                        continue
                    grad = p.grad
                    if grad.is_sparse:
                        raise RuntimeError('RAdam does not support sparse gradients')
                    state = self.state[p]
                    if len(state) == 0:
                        state['step'] = 0
                        state['exp_avg'] = torch.zeros_like(p)
                        state['exp_avg_sq'] = torch.zeros_like(p)
                    exp_avg, exp_avg_sq = state['exp_avg'], state['exp_avg_sq']
                    beta1, beta2 = group['betas']
                    state['step'] += 1
                    t = state['step']
                    # Decoupled weight decay
                    if group['weight_decay'] != 0:
                        p.mul_(1 - group['lr'] * group['weight_decay'])
                    # Update biased first moment estimate
                    exp_avg.mul_(beta1).add_(grad, alpha=1 - beta1)
                    # Update biased second raw moment estimate
                    exp_avg_sq.mul_(beta2).addcmul_(grad, grad, value=1 - beta2)
                    # Compute bias-corrected first moment estimate
                    m_hat = exp_avg / (1 - beta1 ** t)
                    # Compute maximum length of the approximated SMA
                    beta2_t = beta2 ** t
                    N_sma_max = 2 / (1 - beta2) - 1
                    N_sma = N_sma_max - 2 * t * beta2_t / (1 - beta2_t)
                    if N_sma >= 5:
                        # Variance rectification term
                        r_t = math.sqrt((N_sma - 4) * (N_sma - 2) * N_sma_max / ((N_sma_max - 4) * (N_sma_max - 2) * N_sma))
                        # Adaptive learning rate
                        denom = exp_avg_sq.sqrt().add_(group['eps'])
                        step_size = group['lr'] * r_t
                        p.addcdiv_(m_hat, denom, value=-step_size)
                    else:
                        # Un-adapted learning rate
                        step_size = group['lr'] / (1 - beta1 ** t)
                        p.add_(exp_avg, alpha=-step_size)

    # Create inner RAdam optimizer
    inner_opt = RAdam(optim_groups, lr=learning_rate, betas=betas, weight_decay=weight_decay)

    # Lookahead wrapper
    class Lookahead(torch.optim.Optimizer):
        """Lookahead optimizer wrapper (Zhang et al., 2019)."""
        def __init__(self, optimizer, k=5, alpha=0.5):
            self.optimizer = optimizer
            self.k = k
            self.alpha = alpha
            self.param_groups = optimizer.param_groups
            self.state = {}
            self._step = 0
            # Initialize slow weights
            for group in self.param_groups:
                for p in group['params']:
                    self.state[p] = {'slow_param': p.data.clone()}

        @torch.no_grad()
        def step(self):
            self._step += 1
            # Inner optimizer step
            self.optimizer.step()
            # Lookahead step every k iterations
            if self._step % self.k == 0:
                for group in self.param_groups:
                    for p in group['params']:
                        slow = self.state[p]['slow_param']
                        # Update slow weights: slow = slow + alpha * (fast - slow)
                        slow.add_(p.data - slow, alpha=self.alpha)
                        # Update fast weights: fast = slow
                        p.data.copy_(slow)

        def zero_grad(self, set_to_none=True):
            self.optimizer.zero_grad(set_to_none=set_to_none)

        def state_dict(self):
            return self.optimizer.state_dict()

        def load_state_dict(self, state_dict):
            self.optimizer.load_state_dict(state_dict)

    optimizer = Lookahead(inner_opt, k=5, alpha=0.5)
    print("using Lookahead-RAdam optimizer")
    return optimizer

